/**
 * Stub of `@deepseek-ai/dsh-llm` — the symbols the doctor imports.
 */

export const CONTEXT_WINDOW_EXCEEDED_CODE = "CONTEXT_WINDOW_EXCEEDED";

export class LlmError extends Error {
  constructor(message, code, options = {}) {
    super(message);
    this.name = "LlmError";
    this.code = code;
    if (options.cause !== undefined) this.cause = options.cause;
  }
}

export class BlockAssembler {
  constructor() {
    this.blocks = [];
  }

  push(block) {
    this.blocks.push(block);
    return this;
  }

  finish() {
    return this.blocks;
  }
}

export function createUserMessage(content) {
  return { role: "user", content };
}

export function contentHasImage() {
  return false;
}

export function errorChain(error) {
  const chain = [];
  let current = error;
  let depth = 0;
  while (current !== undefined && current !== null && depth < 8) {
    chain.push(current);
    current = current.cause;
    depth += 1;
  }
  return chain;
}

export default { CONTEXT_WINDOW_EXCEEDED_CODE, LlmError, BlockAssembler, createUserMessage, contentHasImage, errorChain };
